CREATE TABLE messes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,seats INT NOT NULL CHECK(seats>0),status VARCHAR(24) NOT NULL DEFAULT 'OPEN');
CREATE TABLE profiles(user_id BIGINT PRIMARY KEY REFERENCES accounts(id),mess_id BIGINT REFERENCES messes(id),hostel VARCHAR(100) NOT NULL DEFAULT '',room VARCHAR(30) NOT NULL DEFAULT '',diet VARCHAR(30) NOT NULL DEFAULT 'VEGETARIAN',allergens VARCHAR(500) NOT NULL DEFAULT '',plan_active BOOLEAN NOT NULL DEFAULT FALSE,permissions VARCHAR(500) NOT NULL DEFAULT '');
CREATE TABLE menu_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),name VARCHAR(120) NOT NULL,meal VARCHAR(20) NOT NULL,meal_date DATE NOT NULL,price_cents BIGINT NOT NULL DEFAULT 0 CHECK(price_cents>=0),available BOOLEAN NOT NULL DEFAULT TRUE,vegetarian BOOLEAN NOT NULL DEFAULT TRUE,allergens VARCHAR(500) NOT NULL DEFAULT '',calories INT NOT NULL DEFAULT 0,protein INT NOT NULL DEFAULT 0);
CREATE TABLE meal_slots(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),meal VARCHAR(20) NOT NULL,meal_date DATE NOT NULL,starts_at TIMESTAMP WITH TIME ZONE NOT NULL,ends_at TIMESTAMP WITH TIME ZONE NOT NULL,capacity INT NOT NULL CHECK(capacity>0),CHECK(ends_at>starts_at));
CREATE TABLE bookings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),slot_id BIGINT NOT NULL REFERENCES meal_slots(id),status VARCHAR(20) NOT NULL DEFAULT 'BOOKED',UNIQUE(user_id,slot_id));
CREATE TABLE queue_entries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,meal VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'WAITING',joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,served_at TIMESTAMP WITH TIME ZONE,UNIQUE(user_id,mess_id,meal_date,meal));
CREATE TABLE qr_passes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,token_hash VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,meal VARCHAR(20) NOT NULL,booking_id BIGINT REFERENCES bookings(id),expires_at TIMESTAMP WITH TIME ZONE NOT NULL,redeemed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE attendance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,meal VARCHAR(20) NOT NULL,claimed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,mess_id,meal_date,meal));
CREATE TABLE tables_state(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),label VARCHAR(30) NOT NULL,seats INT NOT NULL CHECK(seats>0),status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE');
CREATE TABLE wallets(user_id BIGINT PRIMARY KEY REFERENCES accounts(id),balance_cents BIGINT NOT NULL DEFAULT 0 CHECK(balance_cents>=0));
CREATE TABLE orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),status VARCHAR(20) NOT NULL DEFAULT 'PLACED',total_cents BIGINT NOT NULL CHECK(total_cents>=0),created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id),menu_id BIGINT NOT NULL REFERENCES menu_items(id),name VARCHAR(120) NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_cents BIGINT NOT NULL CHECK(unit_cents>=0));
CREATE TABLE wallet_transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),amount_cents BIGINT NOT NULL,kind VARCHAR(30) NOT NULL,order_id BIGINT REFERENCES orders(id),reference VARCHAR(120) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,reference));
CREATE TABLE coupons(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),code VARCHAR(30) NOT NULL,discount_percent INT NOT NULL CHECK(discount_percent BETWEEN 1 AND 80),minimum_cents BIGINT NOT NULL DEFAULT 0,expires_on DATE NOT NULL,usage_limit INT NOT NULL CHECK(usage_limit>0),UNIQUE(mess_id,code));
CREATE TABLE coupon_usage(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,coupon_id BIGINT NOT NULL REFERENCES coupons(id),user_id BIGINT NOT NULL REFERENCES accounts(id),order_id BIGINT NOT NULL REFERENCES orders(id),UNIQUE(coupon_id,user_id));
CREATE TABLE inventory(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),name VARCHAR(120) NOT NULL,unit VARCHAR(20) NOT NULL,quantity DECIMAL(14,3) NOT NULL CHECK(quantity>=0),minimum DECIMAL(14,3) NOT NULL CHECK(minimum>=0),expires_on DATE,supplier VARCHAR(120) NOT NULL DEFAULT '');
CREATE TABLE stock_transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id BIGINT NOT NULL REFERENCES inventory(id),actor_id BIGINT NOT NULL REFERENCES accounts(id),change_qty DECIMAL(14,3) NOT NULL,reason VARCHAR(200) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recipes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),name VARCHAR(120) NOT NULL,base_servings INT NOT NULL CHECK(base_servings>0),ingredients TEXT NOT NULL);
CREATE TABLE kitchen_batches(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),name VARCHAR(120) NOT NULL,servings INT NOT NULL CHECK(servings>0),status VARCHAR(20) NOT NULL DEFAULT 'PLANNED',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE waste_records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),actor_id BIGINT NOT NULL REFERENCES accounts(id),meal_date DATE NOT NULL,prepared_kg DECIMAL(14,3) NOT NULL CHECK(prepared_kg>0),waste_kg DECIMAL(14,3) NOT NULL CHECK(waste_kg>=0 AND waste_kg<=prepared_kg),note VARCHAR(300) NOT NULL DEFAULT '');
CREATE TABLE safety_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),actor_id BIGINT NOT NULL REFERENCES accounts(id),item VARCHAR(120) NOT NULL,temperature DECIMAL(6,2),note VARCHAR(500) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE complaints(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),category VARCHAR(40) NOT NULL,description VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED',resolution VARCHAR(2000) NOT NULL DEFAULT '',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE feedback(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(1000) NOT NULL,UNIQUE(user_id,mess_id,meal_date));
CREATE TABLE skip_meals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,meal VARCHAR(20) NOT NULL,UNIQUE(user_id,mess_id,meal_date,meal));
CREATE TABLE favourites(user_id BIGINT NOT NULL REFERENCES accounts(id),menu_id BIGINT NOT NULL REFERENCES menu_items(id),PRIMARY KEY(user_id,menu_id));
CREATE TABLE announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),title VARCHAR(150) NOT NULL,body VARCHAR(2000) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE polls(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),question VARCHAR(150) NOT NULL,options_text VARCHAR(1000) NOT NULL,closes_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE votes(poll_id BIGINT NOT NULL REFERENCES polls(id),user_id BIGINT NOT NULL REFERENCES accounts(id),choice INT NOT NULL,PRIMARY KEY(poll_id,user_id));
CREATE TABLE events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),title VARCHAR(150) NOT NULL,starts_at TIMESTAMP WITH TIME ZONE NOT NULL,capacity INT NOT NULL CHECK(capacity>0));
CREATE TABLE event_bookings(event_id BIGINT NOT NULL REFERENCES events(id),user_id BIGINT NOT NULL REFERENCES accounts(id),PRIMARY KEY(event_id,user_id));
CREATE TABLE guest_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT NOT NULL REFERENCES messes(id),guest_name VARCHAR(100) NOT NULL,visit_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING');
CREATE TABLE points_ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),points INT NOT NULL,reason VARCHAR(120) NOT NULL,reference VARCHAR(100) NOT NULL,UNIQUE(user_id,reference));
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),message VARCHAR(500) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT NOT NULL REFERENCES accounts(id),mess_id BIGINT REFERENCES messes(id),action VARCHAR(100) NOT NULL,detail VARCHAR(500) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE command_receipts(user_id BIGINT NOT NULL REFERENCES accounts(id),request_id VARCHAR(80) NOT NULL,payload_hash VARCHAR(64) NOT NULL,response_json TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,request_id));
CREATE TABLE ai_messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES accounts(id),question VARCHAR(1000) NOT NULL,answer TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE forecast_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mess_id BIGINT NOT NULL REFERENCES messes(id),meal_date DATE NOT NULL,meal VARCHAR(20) NOT NULL,predicted INT NOT NULL,actual INT,method VARCHAR(200) NOT NULL,UNIQUE(mess_id,meal_date,meal));
CREATE TABLE device_tokens(user_id BIGINT NOT NULL REFERENCES accounts(id),token VARCHAR(1000) NOT NULL,PRIMARY KEY(user_id,token));
CREATE INDEX idx_menu_day ON menu_items(mess_id,meal_date);
CREATE INDEX idx_queue_service ON queue_entries(mess_id,meal_date,meal,status);
CREATE INDEX idx_slots_service ON meal_slots(mess_id,meal_date,meal);
CREATE INDEX idx_orders_mess ON orders(mess_id,status);
CREATE INDEX idx_attendance_service ON attendance(mess_id,meal_date,meal);
CREATE INDEX idx_notifications_user ON notifications(user_id,is_read);
CREATE INDEX idx_forecast_day ON forecast_history(mess_id,meal_date);
